#!/usr/bin/env python3
"""FlowPilot AI — HARDENING-MASTER apply engine (unconditional enterprise sign-off).

Brings a tree at the TIER 4 baseline (commit fd7f062) to the HARDENING-MASTER
state: 54 file operations (46 modify, 8 add) across backend and
frontend — the $799 self-serve Enterprise plan, the four-tier capability
matrix and its gates, FlowPilot's own unsaved-changes dialog, the partner
manifest console, migration hm1_tier_price_per_key and
verify_hardening_master.py.

Run from the repository root (the folder holding backend/ and frontend/):

    python apply_hardening_master.py --check      # verify every file; write nothing
    python apply_hardening_master.py              # apply (atomic, with backup)
    python apply_hardening_master.py              # second run: reports no changes
    python apply_hardening_master.py --rollback   # restore the latest backup

SAFETY
  * Every modified file must match its TIER 4 content (sha256 over text with
    CRLF normalised to LF and any UTF-8 BOM removed), or already match the
    master content. Anything else is a CONFLICT and nothing is written —
    local edits are never overwritten.
  * All files are checked before any is written. Originals are copied to
    .hardening_master_apply_backup/<timestamp>/ first; a failure mid-write
    restores them.
  * Line endings: a modified file keeps the style it has on disk (CRLF on a
    Windows checkout). New files use CRLF on Windows, LF elsewhere. Python
    files are written without a BOM.
  * The migration is NOT run here. run_hardening_master.ps1 upgrades to
    hm1_tier_price_per_key explicitly, never to `head` (the lossy ARCH-40
    contract step stays behind its flag).
"""

